package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.UpdatedAtVO;

class UpdatedAtValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of updated at of user profile")
  void test_updated_at_value_holder_assign_plain_value() {
    Object holder = new Object();
    UpdatedAtValueHolder<Object> value = new UpdatedAtValueHolder<>(holder);
    Assertions.assertSame(holder, value.updatedAt("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getUpdatedAtValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getUpdatedAt().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.updatedAtNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getUpdatedAtValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getUpdatedAt().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of updated at of user profile")
  void test_updated_at_value_holder_assign_value_object() {
    Object holder = new Object();
    UpdatedAtValueHolder<Object> value = new UpdatedAtValueHolder<>(holder);
    UpdatedAtVO vo = UpdatedAtVO.from("one");
    Assertions.assertFalse(value.getUpdatedAtValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.updatedAt(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getUpdatedAtValue().orElseThrow());
    Assertions.assertSame(holder, value.updatedAt(Optional.empty()));
    Assertions.assertFalse(value.getUpdatedAtValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.updatedAt(Optional.of(vo)));
    Assertions.assertSame(vo, value.getUpdatedAtValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of updated at of user profile against the original")
  void test_updated_at_value_holder_read() {
    Object holder = new Object();
    UpdatedAtValueHolder<Object> value = new UpdatedAtValueHolder<>(holder);
    UpdatedAtVO vo = UpdatedAtVO.from("one");
    UpdatedAtVO other = UpdatedAtVO.from("one");
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getUpdatedAtValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readUpdatedAt(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readUpdatedAt(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.updatedAt(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readUpdatedAt(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readUpdatedAt(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of updated at of user profile")
  void test_updated_at_value_holder_unset() {
    Object holder = new Object();
    UpdatedAtValueHolder<Object> value = new UpdatedAtValueHolder<>(holder);
    UpdatedAtVO vo = UpdatedAtVO.from("one");
    value.updatedAt(vo);
    Assertions.assertSame(holder, value.unsetUpdatedAtIfMatches("updatedAt_other"));
    Assertions.assertTrue(value.getUpdatedAtValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetUpdatedAtIfMatches("updatedAt"));
    Assertions.assertFalse(value.getUpdatedAtValue().isPresent(),
        "The field name must clear the value");
    value.updatedAt(vo);
    Assertions.assertSame(holder, value.unsetUpdatedAt());
    Assertions.assertFalse(value.getUpdatedAtValue().isPresent(), "Unset must clear the value");
  }
}
